-- ===== 000_extensions.sql =====
-- StoreMaster uses no PostGIS spatial types; no optional extensions are required.

-- ===== 001_schema.sql =====
CREATE TABLE IF NOT EXISTS "Stores" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "Code" text NOT NULL,
  "Name" text NOT NULL,
  "Type" text NOT NULL,
  "BusinessTitle" text NOT NULL,
  "Currency" text NOT NULL,
  "Active" boolean NOT NULL DEFAULT true,
  "CreatedAt" timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_Stores_Code" ON "Stores" ("Code");

CREATE TABLE IF NOT EXISTS "Users" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "Username" text NOT NULL DEFAULT 'admin',
  "Name" text NOT NULL,
  "Phone" text NOT NULL,
  "PinHash" text NOT NULL,
  "Active" boolean NOT NULL DEFAULT true,
  "CreatedAt" timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS "IX_Users_Username" ON "Users" ("Username");

CREATE TABLE IF NOT EXISTS "StoreUsers" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "StoreId" integer NOT NULL,
  "UserId" integer NOT NULL,
  "Role" text NOT NULL,
  "PermissionsJson" text NOT NULL DEFAULT '[]',
  "Active" boolean NOT NULL DEFAULT true
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_StoreUsers_StoreId_UserId" ON "StoreUsers" ("StoreId","UserId");
CREATE INDEX IF NOT EXISTS "IX_StoreUsers_UserId" ON "StoreUsers" ("UserId");

CREATE TABLE IF NOT EXISTS "Licenses" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "StoreId" integer NOT NULL,
  "LicenseId" text NOT NULL,
  "ActivationCode" text NOT NULL DEFAULT '',
  "ActivationCodeUsed" boolean NOT NULL DEFAULT false,
  "Plan" text NOT NULL,
  "Status" text NOT NULL,
  "IssuedAt" timestamptz NOT NULL DEFAULT now(),
  "ExpiresAt" timestamptz NOT NULL,
  "OriginalPrice" numeric NOT NULL,
  "FinalPrice" numeric NOT NULL,
  "DiscountCode" text NOT NULL DEFAULT '',
  "FeaturesJson" text NOT NULL DEFAULT '[]',
  "BusinessTypesJson" text NOT NULL DEFAULT '["*"]',
  "MaxUsers" integer NOT NULL DEFAULT 5,
  "Username" text NOT NULL DEFAULT 'admin',
  "InitialPassword" text NOT NULL DEFAULT '',
  "RecoveryCode" text NOT NULL DEFAULT ''
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_Licenses_LicenseId" ON "Licenses" ("LicenseId");
CREATE UNIQUE INDEX IF NOT EXISTS "IX_Licenses_ActivationCode" ON "Licenses" ("ActivationCode") WHERE "ActivationCode" <> '';
CREATE INDEX IF NOT EXISTS "IX_Licenses_StoreId" ON "Licenses" ("StoreId");

CREATE TABLE IF NOT EXISTS "DiscountCodes" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "Code" text NOT NULL,
  "Percent" integer NOT NULL,
  "FixedAmount" numeric NOT NULL,
  "MaxUses" integer NOT NULL,
  "UsedCount" integer NOT NULL DEFAULT 0,
  "ExpiresAt" timestamptz NULL,
  "Active" boolean NOT NULL DEFAULT true
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_DiscountCodes_Code" ON "DiscountCodes" ("Code");

CREATE TABLE IF NOT EXISTS "SyncChanges" (
  "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "StoreId" integer NOT NULL,
  "UserId" integer NOT NULL,
  "Entity" text NOT NULL,
  "Operation" text NOT NULL,
  "EntityId" text NOT NULL,
  "PayloadJson" text NOT NULL DEFAULT '{}',
  "CreatedAt" timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS "IX_SyncChanges_StoreId_Id" ON "SyncChanges" ("StoreId","Id");

CREATE TABLE IF NOT EXISTS "UserDevices" (
  "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "StoreId" integer NOT NULL,
  "UserId" integer NOT NULL,
  "DeviceId" text NOT NULL,
  "Platform" text NOT NULL,
  "Name" text NOT NULL,
  "FirstSeenAt" timestamptz NOT NULL DEFAULT now(),
  "LastSeenAt" timestamptz NOT NULL DEFAULT now(),
  "Active" boolean NOT NULL DEFAULT true
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_UserDevices_StoreId_UserId_DeviceId" ON "UserDevices" ("StoreId","UserId","DeviceId");

CREATE TABLE IF NOT EXISTS "CloudRecords" (
  "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "StoreId" integer NOT NULL,
  "Entity" text NOT NULL,
  "EntityId" text NOT NULL,
  "Operation" text NOT NULL DEFAULT 'UPSERT',
  "PayloadJson" text NOT NULL DEFAULT '{}',
  "SourceVersion" bigint NOT NULL DEFAULT 0,
  "UpdatedAt" timestamptz NOT NULL DEFAULT now(),
  "UserId" integer NOT NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_CloudRecords_StoreId_Entity_EntityId" ON "CloudRecords" ("StoreId","Entity","EntityId");

CREATE TABLE IF NOT EXISTS "PricingEntries" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "PlanDays" integer NOT NULL,
  "Price" numeric NOT NULL,
  "Currency" text NOT NULL DEFAULT 'تومان',
  "UpdatedAt" timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_PricingEntries_PlanDays" ON "PricingEntries" ("PlanDays");

CREATE TABLE IF NOT EXISTS "SupportTickets" (
  "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "TicketCode" text NOT NULL,
  "Type" text NOT NULL DEFAULT 'SUPPORT',
  "StoreCode" text NOT NULL DEFAULT '',
  "LicenseId" text NOT NULL DEFAULT '',
  "Username" text NOT NULL DEFAULT 'admin',
  "DeviceId" text NOT NULL DEFAULT '',
  "Contact" text NOT NULL DEFAULT '',
  "Message" text NOT NULL DEFAULT '',
  "Status" text NOT NULL DEFAULT 'OPEN',
  "CreatedAt" timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_SupportTickets_TicketCode" ON "SupportTickets" ("TicketCode");

INSERT INTO "PricingEntries" ("PlanDays","Price","Currency") VALUES
  (30,990000,'تومان'), (90,2490000,'تومان'), (180,4490000,'تومان'), (365,7990000,'تومان')
ON CONFLICT ("PlanDays") DO NOTHING;

-- ===== 002_constraints.sql =====
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='fk_storeusers_store') THEN
    ALTER TABLE "StoreUsers" ADD CONSTRAINT fk_storeusers_store FOREIGN KEY ("StoreId") REFERENCES "Stores"("Id") ON DELETE CASCADE;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='fk_storeusers_user') THEN
    ALTER TABLE "StoreUsers" ADD CONSTRAINT fk_storeusers_user FOREIGN KEY ("UserId") REFERENCES "Users"("Id") ON DELETE CASCADE;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='fk_licenses_store') THEN
    ALTER TABLE "Licenses" ADD CONSTRAINT fk_licenses_store FOREIGN KEY ("StoreId") REFERENCES "Stores"("Id") ON DELETE CASCADE;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='fk_devices_storeuser') THEN
    ALTER TABLE "UserDevices" ADD CONSTRAINT fk_devices_storeuser FOREIGN KEY ("StoreId","UserId") REFERENCES "StoreUsers"("StoreId","UserId") ON DELETE CASCADE;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='fk_cloud_store') THEN
    ALTER TABLE "CloudRecords" ADD CONSTRAINT fk_cloud_store FOREIGN KEY ("StoreId") REFERENCES "Stores"("Id") ON DELETE CASCADE;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='fk_sync_store') THEN
    ALTER TABLE "SyncChanges" ADD CONSTRAINT fk_sync_store FOREIGN KEY ("StoreId") REFERENCES "Stores"("Id") ON DELETE CASCADE;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='fk_sync_user') THEN
    ALTER TABLE "SyncChanges" ADD CONSTRAINT fk_sync_user FOREIGN KEY ("UserId") REFERENCES "Users"("Id") ON DELETE RESTRICT;
  END IF;
END $$;

CREATE INDEX IF NOT EXISTS "IX_Users_Username_Lower" ON "Users" (lower("Username"));
CREATE INDEX IF NOT EXISTS "IX_StoreUsers_StoreId_Active" ON "StoreUsers" ("StoreId","Active");
CREATE INDEX IF NOT EXISTS "IX_Licenses_StoreId_Status_ExpiresAt" ON "Licenses" ("StoreId","Status","ExpiresAt");
CREATE INDEX IF NOT EXISTS "IX_SyncChanges_StoreId_Id" ON "SyncChanges" ("StoreId","Id");

-- ===== 003_schema_version.sql =====
CREATE TABLE IF NOT EXISTS "SchemaVersions" (
  "Version" integer PRIMARY KEY,
  "AppliedAt" timestamptz NOT NULL DEFAULT now()
);
INSERT INTO "SchemaVersions"("Version") VALUES (3) ON CONFLICT ("Version") DO NOTHING;

-- ===== 004_online_features.sql =====
-- StoreMaster online support, secure invoice links and central trial policy.
-- Idempotent; may be run after 001_schema.sql on an existing database.
ALTER TABLE "SupportTickets"
  ADD COLUMN IF NOT EXISTS "AccessTokenHash" text NOT NULL DEFAULT '';

CREATE TABLE IF NOT EXISTS "SupportMessages" (
  "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "TicketId" bigint NOT NULL,
  "SenderRole" text NOT NULL DEFAULT 'CUSTOMER',
  "SenderName" text NOT NULL DEFAULT 'کاربر',
  "Message" text NOT NULL DEFAULT '',
  "CreatedAt" timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS "IX_SupportMessages_TicketId_Id"
  ON "SupportMessages" ("TicketId", "Id");

CREATE TABLE IF NOT EXISTS "InvoiceShares" (
  "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "Token" text NOT NULL,
  "StoreId" integer NOT NULL,
  "StoreName" text NOT NULL DEFAULT '',
  "StorePhone" text NOT NULL DEFAULT '',
  "InvoiceNumber" text NOT NULL DEFAULT '',
  "DateText" text NOT NULL DEFAULT '',
  "CustomerName" text NOT NULL DEFAULT '',
  "Currency" text NOT NULL DEFAULT 'تومان',
  "ItemsJson" text NOT NULL DEFAULT '[]',
  "TotalAmount" numeric NOT NULL DEFAULT 0,
  "Discount" numeric NOT NULL DEFAULT 0,
  "FinalAmount" numeric NOT NULL DEFAULT 0,
  "PaidAmount" numeric NOT NULL DEFAULT 0,
  "DebtAmount" numeric NOT NULL DEFAULT 0,
  "CreatedAt" timestamptz NOT NULL DEFAULT now(),
  "ExpiresAt" timestamptz NOT NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_InvoiceShares_Token" ON "InvoiceShares" ("Token");
CREATE INDEX IF NOT EXISTS "IX_InvoiceShares_StoreId_CreatedAt" ON "InvoiceShares" ("StoreId", "CreatedAt");

CREATE TABLE IF NOT EXISTS "TrialPolicies" (
  "Id" integer PRIMARY KEY,
  "FeaturesJson" text NOT NULL DEFAULT '["sales","customers","products"]',
  "BusinessTypesJson" text NOT NULL DEFAULT '["*"]',
  "UpdatedAt" timestamptz NOT NULL DEFAULT now()
);
INSERT INTO "TrialPolicies" ("Id") VALUES (1) ON CONFLICT ("Id") DO NOTHING;
